String stringXor(String a, String b) {
  final List<int> xorList = [];

  for (int i = 0; i < max(a.length, b.length); ++i) {
    int charA = a.codeUnitAt(i % a.length);
    int charB = b.codeUnitAt(i % b.length);

    int xorByte = charA ^ charB;
    xorList.add(xorByte);
  }

  return String.fromCharCodes(xorList);
