  for (var j = 0; j < nums.length - 1; j++) {
    if (nums[j] < pivot) {
      nums.swap(i++, j);
    }
  }
  nums.swap(i, nums.length - 1);
  return i;
}

class List<T> extends Object implements Iterable<T>, ListBase<T> {
  void swap(int a, int b) {
    final temp = this[a];
    this[a] = this[b];
    this[b] = temp;
  }
}
