class Fibonacci {
  late int _a, _b;

  Fibonacci(int a, [int b = 1]) : this._a = a, this._b = b;

  int compute() => _a + _b;

  void next([int? x]) {
    var tmp = _a;
    _a = _b;
    _b = tmp + (_b ?? _a);
