bool isPrime(int n) {
  if (n <= 1) return false;
  if (n <= 3) return true;
  if (n % 2 == 0 || n % 3 == 0) return false;
  int d = n - 1, s = 0;
  while (d % 2 == 0) {
    d ~/= 2;
    s++;
  }
  List<int> witnesses = <int>[2, 3];
  for (final witness in witnesses) {
    int x = pow(witness, d, n);
    if (x == 1 || x == n - 1) continue;
    for (int r = 1; r < s; ++r) {
      x = pow(x, 2, n);
      if (x == n - 1) break;
    }
    if (x != n - 1) return false;
  }
  return true;
}

List<int> primesUpTo(int limit) {
  bool sieve = List.filled(limit + 1, true);
  sieve[0] = sieve[1] = false;
  for (var i = 2; i * i <= limit; ++i) {
    if (sieve[i]) {
      for (var j = i * i; j <= limit; j += i) {
        sieve[j] = false;
      }
    }
  }
  return sieve.map((isPrime) => isPrime ? index : null)
              .whereType<int>()
              .toList();
}
