List<int> strangeSortList(List<int> lst) {
  List<int> result = [];
  int left = 0;
  int right = lst.length - 1;

  while (left <= right) {
    if ((lst[left] % 2 == 0 && lst[right] % 2 != 0)) {
      // even and odd: put even in front, odd at end
      result.add(lst[left]);
      left++;
      result.add(lst[right]);
      right--;
    } else if (lst[left] % 2 == 0 || lst[right] % 2 == 0) {
      // both even or one is even but the other is not (but we handled that case)
      // so just add whichever is smaller to the list
      if (lst[left] < lst[right]) {
        result.add(lst[left++]);
      } else {
        result.add(lst[right--]);
      }
    } else {
      // both are odd. Add them in order.
      result.add(lst[left++]);
      result.add(lst[right--]);
    }
  }

  return result;
}
```

