  int n = lst.length;
  List<int> result = List.filled(n, 0);

  // Initialize two pointers for the left and right ends of the list.
  int left = 0, right = n - 1;

  // Iterate through each element in the list.
  for (int i = 0; i < n; i++) {
    if (i % 2 == 0) {
      // If index is even, place the smallest remaining number at this position.
      result[i] = lst[left];
      left++;
    } else {
      // If index is odd, place the largest remaining number at this position.
      result[i] = lst[right];
      right--;
    }
  }

