List<int> strangeSortList(List<int> lst) {
  final n = lst.length;
  if (n == 0 || n == 1) return List.from(lst);

  for (int i = 0; i < n - 1; i++) {
    int minIndex = i;
    for (int j = i + 1; j < n; j++) {
      if (lst[j] < lst[minIndex]) {
        minIndex = j;
      }
    }
    // Swap the found minimum element with the first unsorted element
    var temp = lst[i];
    lst[i] = lst[minIndex];
    lst[minIndex] = temp;
  }

  // Separate even and odd numbers into two lists
  List<int> evens = [];
  List<int> odds = [];

  for (var num in lst) {
    if (num % 2 == 0) {
      evens.add(num);
    } else {
      odds.add(num);
    }
  }

  // Merge them back by alternating between evens and odds, starting with even
  List<int> result = [];
  bool nextEven = true;

  while (evens.isNotEmpty || odds.isNotEmpty) {
    if (nextEven && evens.isNotEmpty) {
      result.add(evens.removeAt(0));
    } else if (!nextEven && odds.isNotEmpty) {
      result.add(odds.removeAt(0));
    } else break;
    nextEven = !nextEven;
  }

  return result;
}
