// Helper function to calculate Levenshtein distance between two strings
int levenshteinDistance(String s, String t) {
  final m = s.length;
  final n = t.length;

  final dp = List.generate(m + 1, (_) => List<int>.filled(n + 1, 0));

  for (int i = 0; i <= m; ++i) {
    dp[i][0] = i;
  }

  for (int j = 0; j <= n; ++j) {
    dp[0][j] = j;
  }

  for (int i = 1; i <= m; ++i) {
    for (int j = 1; j <= n; ++j) {
      final cost = (s[i - 1] == t[j - 1]) ? 0 : 1;
      dp[i][j] = min(
        dp[i - 1][j] + 1,
        dp[i][j - 1] + 1,
        dp[i - 1][j - 1] + cost,
      );
    }
  }

  return dp[m][n];
}

