  bool _isValidKey(String key) {
    // Ensure keys are strings
    if (!(key is String)) return false;

    // Check if the key is in snake_case format with optional leading _
    if (key.isEmpty) return false;

    int lastUnderscoreIndex = key.lastIndexOf('_');

    // No underscores at the beginning or end
    if (lastUnderscoreIndex == 0 || lastUnderscoreIndex == key.length - 1) {
      return false;
