import 'dart:math';

class Solution {
  static final _cache = Map<int, Map<int, int>>();

  static int dfs(int n, int k) {
    if (_cache.containsKey(n) && _cache[n]!.containsKey(k)) {
      return _cache[n]![k]!;
    }

    if (n <= 0) return 1;
    if (k > n) return 0;

    var res = dfs(n - 1, k - 1) + dfs(n - 1, k);
    _cache[n] ??= {};
    _cache[n]![k] = res;
    return res;
  }

  static int solve(int x, int y) {
    if (x < y) return dfs(y, x);
    return dfs(x, y);
  }
}

void main() {
