List<int> uniqueDigits(List<int> x) {
  final seen = Set<int>();
  final result = <int>[];

  for (final num in x) {
    var currentNum = num;

    while (currentNum > 0) {
      int digit = currentNum % 10;
      if (!seen.contains(digit)) {
        seen.add(digit);
        result.add(digit);
      }
      currentNum ~/= 10;
    }
  }

  return result;
}
