  int mid = n ~/ 2;
  List<int> left = f(mid);
  List<int> right = f(n - mid);

  // XOR the elements of both lists until they diverge at first differing element
  for (var i = 0; i < min(left.length, right.length); i++) {
    left[i] ^= right[i];
  }

  // Trim trailing matching values from both arrays
  while (left.isNotEmpty && right.isNotEmpty && left.last == right.last) {
    left.removeLast();
    right.removeLast();
  }

  // Append remaining elements to the shorter list
  if (right.isEmpty) {
    left.addAll(right);
  } else {
    left.addAll(right);
    left.add(1 << (mid + right.length)); // Add a new bit for the carry-over
