  for (int i = 0; i < n - 1; ++i) {
    if (arr[i] != arr[i + 1]) {
      // Swap with next element to simulate moving it one step forward.
      final temp = arr[i];
      arr[i] = arr[i + 1];
      arr[i + 1] = temp;
      return true;
    }
  }

  // If no such position is found, we need to check from the end and loop around.
  if (arr[n - 1] != arr[0]) {
    final temp = arr[n - 1];
    arr[n - 1] = arr[0];
    arr[0] = temp;
    return true;
  }

  return false;
}
