import 'dart:math';

class Solution {
  static bool moveOneBall(List<int> balls) {
    final queue = Queue<int>();

    // Add all the balls to a queue
    for (var ball in balls) {
      queue.add(ball);
    }

    while (queue.isNotEmpty) {
      var first = queue.removeFirst();

      if (queue.isNotEmpty && queue.first == first) {
        return true;
      } else {
        queue.add(first); // Put it back at the end of the queue
      }
    }

    return false;
  }
}

