int dfs(List<List<int>> grid, List<List<bool>> visited, int row, int col) {
  if (row < 0 || row >= grid.length || col < 0 || col >= grid[row].length || visited[row][col]) {
    return 0;
  }

  if (grid[row][col] == 0) {
    return 0;
  }

  visited[row][col] = true;

  // Check all four directions
  var total = 1;
  total += dfs(grid, visited, row - 1, col); 
  total += dfs(grid, visited, row + 1, col);
  total += dfs(grid, visited, row, col - 1);
  total += dfs(grid, visited, row, col + 1);

  return total;
}
