import 'dart:math';
int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;
  final cols = grid[0].length;
  if (cols == 0) return 0;
  final visited = List.generate(rows, (_) => List.filled(cols, false));
  var result = 0;
  for (var i=0; i<rows; ++i) {
    for (var j=0; j<cols; ++j) {
      if (!visited[i][j] && grid[i][j]>0) {
        final area = dfs(grid, visited, i,j);
        final fill = min(area, capacity);
        result += fill;
        capacity -= fill;
        if (capacity==0) return result;
      }
    }
  }
  return result;
}
int dfs(List<List<int>> g, List<List<bool>> v, int r, int c) {
  if(r<0||r>=g.length||c<0||c>=g[r].length||v[r][c]) return 0;
  if(g[r][c]==0)return 0;
  v[r][c]=true;
  return 1+dfs(g,v,r-1,c)+dfs(g,v,r+1,c)+dfs(g,v,r,c-1)+dfs(g,v,r,c+1);
}
