/// Checks whether the given [date] string is a valid date in "yyyy-MM-dd" format.
///
/// Returns `true` if it's a valid date and not in the future. Otherwise returns `false`.
bool validDate(String date) {
  // Check that the input has exactly three '-' characters to split into year/month/day.
  if (date.split('-').length != 3) return false;

  // Parse each part of the date as integers.
  final parts = date.split('-');
  final yearStr = parts[0];
  final monthStr = parts[1];
  final dayStr = parts[2];

  // Validate that all components are numeric.
  if (
    !yearStr.isDigit() ||
    !monthStr.isDigit() ||
    !dayStr.isDigit()
  ) return false;

  // Attempt to parse them.
  int? year;
  int? month;
  int? day;
  try {
    year = int.parse(yearStr);
    month = int.parse(monthStr);
    day = int.parse(dayStr);
  } on FormatException {
    return false;
  }

  // Ensure we have non-null values.
  if (year == null || month == null || day == null) return false;

  // Check that the date is not in the future.
  return DateTime(year, month, day).isBefore(DateTime.now());
}

