// Dart code to process a string by fixing spaces according to specific rules.

class SpaceFixer {
  static const _whitespacePattern = RegExp(r'\s+');

  static String fixSpaces(String input) {
    final lines = input.split('\n');
    final processedLines = List<String>.generate(lines.length,
        (index) => _processLine(lines[index]));

    return processedLines.join('\n');
  }

  static String _processLine(String line) {
    final trimmed = line.trim(); 
    final normalized = _normalizeWhitespace(trimmed); 

    final parts = normalized.split(_whitespacePattern);

    // Merge adjacent whitespace sequences with single space
    String merged = '';
    bool prevWasSpace = false;
    for (int i = 0; i < parts.length; i++) {
      final part = parts[i];
      if (part.isEmpty) {
        continue;
      }

      if (!prevWasSpace && !merged.isEmpty) {
        merged += ' ';
      }
      merged += part;
      prevWasSpace = part.containsOnlyWhitespaces();
    }

    return merged;
  }

  static bool containsOnlyWhitespaces(String s) =>
      s.isNotEmpty && s.trim().isEmpty;
}

void main() {
