String fixSpaces(String text) {
  if (text.isEmpty) return '';

  List<String> words = [];
  String currentWord = '';
  bool isInsideWord = false;

  for (int i = 0; i < text.length; i++) {
    final char = text[i];

    // Check if the character is a space or tab and we are inside a word
    if (char == ' ' || char == '\t') {
      if (isInsideWord) {
        words.add(currentWord);
        currentWord = '';
        isInsideWord = false;
      }
    } else {
      // If not, check if it's the start of a new word
      if (!isInsideWord && (i == 0 || text[i - 1] == ' ' || text[i - 1] == '\t')) {
        isInsideWord = true;
      }
      currentWord += char;
    }
  }

  // Add any remaining characters in currentWord as the last word
  if (currentWord.isNotEmpty) {
    words.add(currentWord);
  }

  return words.join(' ');
}
