String wordsInSentence(String sentence) {
  final List<String> words = [];
  int wordStartIndex = -1;

  for (int i = 0; i < sentence.length; ++i) {
    if (sentence[i].trim().isNotEmpty && wordStartIndex == -1) {
      wordStartIndex = i;
    } else if (wordStartIndex != -1 && (i == sentence.length || !sentence[i].trim().isNotEmpty)) {
      String word = sentence.substring(wordStartIndex, i);
      // Check if the word is a valid non-empty string and not just whitespace
      if (word.isNotEmpty) {
        words.add(word.trim());
      }
      wordStartIndex = -1;
    }
  }

  return words.join(' ');
}
