    final parsedN = parseExpression(n);

    if (parsedN == null || !expression.isInteger && parsedN.isInteger) return false;

    int valueX = evaluate(expression).toInt();
    int valueN = evaluate(parsedN).toInt();

    // Check for division by zero and negative numbers in denominators
    if (valueN == 0) return false;
    if (valueN < 0) {
      if (valueX < 0) valueX *= -1; 
      else valueN *= -1;
