    List<int> factorsN = factorize(valueN);

    Map<int, int> countFactorsX = _countFactors(factorsX);
    Map<int, int> countFactorsN = _countFactors(factorsN);

    // Find common factors to cancel out
    Set<int> allFactors = countFactorsX.keys.toSet().union(countFactorsN.keys.toSet());
    for (int factor in allFactors) {
      int minCount = math.min(
        countFactorsX.containsKey(factor) ? countFactorsX[factor]! : 0,
        countFactorsN.containsKey(factor) ? countFactorsN[factor]! : 0
      );

      if (minCount > 0) {
        if (countFactorsX.containsKey(factor)) countFactorsX.remove(factor);
        if (countFactorsN.containsKey(factor)) countFactorsN.remove(factor);

        while (minCount-- > 0) {
          if (factor % 2 == 0) {
            if (countFactorsX.containsKey(factor)) countFactorsX.remove(factor);
            if (countFactorsN.containsKey(factor)) countFactorsN.remove(factor);
          } else {
            break;
          }
        }
      }
    }

    bool canSimplify = countFactorsX.isNotEmpty || countFactorsN.isNotEmpty;

    return canSimplify;
  } catch (_) {
    return false;
  }
}

List<int> factorize(int number) {
  if (number <= 1) return [1];

  List<int> factors = [];

  for (var i = 2; i * i <= number; i++) {
    while (number % i == 0) {
      factors.add(i);
      number ~/= i;
    }
  }

  if (number > 1) {
    factors.add(number);
  }

  return factors;
}

Map<int, int> _countFactors(List<int> factors) {
  Map<int, int> counts = {};

  for (int factor in factors) {
    if (!counts.containsKey(factor)) {
      counts[factor] = 0;
    }
    counts[factor] = counts[factor]! + 1;
  }

  return counts;
}
