  for (var i = 0; i < n - 1; i++) {
    var minIndex = i;
    for (var j = i + 1; j < n; j++) {
      if ((nums[j] % 2 == 0 && nums[minIndex] % 2 != 0) ||
          (nums[j] % 2 == 0 && nums[minIndex] % 2 == 0 &&
              nums[j] < nums[minIndex])) {
        minIndex = j;
      }
    }
    // Swap the found minimum element with the first element of the unsorted part
    var temp = nums[i];
    nums[i] = nums[minIndex];
    nums[minIndex] = temp;
  }
  return nums;
}
