String strongestExtension(String className, List<String> extensions) {
  if (extensions.isEmpty || className == null || className.trim().isEmpty) return '';

  // Filter out any empty or whitespace-only extension names
  final validExtensions = extensions.where((e) => e.trim() != '').toList();

  if (validExtensions.isEmpty) return '';

  var maxScore = -1;
  String bestExt = '';

  for (var ext in validExtensions) {
    int score = _calculateExtensionStrength(ext);

    if (score > maxScore) {
      maxScore = score;
      bestExt = ext;
    }
  }

  return bestExt;
}

int _calculateExtensionStrength(String ext) {
  // Split into parts based on underscores and hyphens as separators
  final segments = ext.split(RegExp(r'[_-]'));
  int totalLength = 0;

  for (final segment in segments) {
    if (segment.isNotEmpty) {
      // Add length of the segment
      totalLength += segment.length;

      // Add number of vowels in the segment
      int vowelCount = 0;
      for (char c in segment.toLowerCase()) {
        if ('aeiou'.contains(c)) vowelCount++;
      }
      totalLength += vowelCount * 2;

      // Add number of consonants in the segment
      int consonantCount = 0;
      for (char c in segment.toLowerCase()) {
        if (!'aeiou'.contains(c) && !c.isWhitespace) consonantCount++;
      }
      totalLength -= consonantCount / 3; // Subtract a fraction to favor more complex patterns

      // Penalize longer words with fewer vowels
      double wordComplexity = (vowelCount + consonantCount).toDouble();
      if (wordComplexity < 5) {
        totalLength -= (5.0 - wordComplexity) * 4; // More penalty for less complex words
      }
    }
  }

  // Favor extensions that are not too long (max 8 characters)
  if (ext.length > 8) {
    totalLength -= (ext.length - 8) * 2;
  }

  return totalLength.round();
}
```

This Dart function `strongestExtension` determines which extension is considered "stronger" by calculating a composite score based on several factors:

1. **Segment Length**: Longer segments contribute more points.
2. **Vowel Count**: Each vowel adds extra value.
3. **Consonant Contribution**: Consonants add some base value but less than vowels.
4. **Word Complexity**: Words with more complexity (more letters overall) get bonus points.
5. **Short Extensions Penalty**: Very long extensions are penalized.

The algorithm gives priority to extensions that have:
- Longer and more complex segments
- Higher vowel content
- Balanced consonant-vowel ratios
- Shorter lengths (up to 8 characters)

The scoring system encourages well-balanced, linguistically meaningful extensions while avoiding overly long or simple ones.

