String strongestExtension(String className, List<String> extensions) {
  if (extensions.isEmpty) return '';

  var extensionMap = <String, int>{};
  for (var ext in extensions) {
    final parts = ext.split('.').reversed.toList();
    String? currentName;
    int priority = 0;

    // Determine the name and version of the extension.
    for (int i = 0; i < parts.length && parts[i] != null; i++) {
      if (i == 0) {
        currentName = parts[i];
      } else {
        if (currentName == null || !isDigit(parts[i]!)) {
          break;
        }
        currentName += '.' + parts[i];
        priority = int.parse(parts[i]);
      }
    }

    if (extensionMap.containsKey(currentName)) {
      extensionMap[currentName] = max(extensionMap[currentName]!, priority);
    } else {
      extensionMap[currentName] = priority;
    }
  }

  Map<ExtensionInfo, dynamic> sortedExtensions = {};
  for (final entry in extensionMap.entries) {
    sortedExtensions[ExtensionInfo.fromEntry(entry)] = entry.value;
  }

  ExtensionInfo topExt = sortedExtensions.keys.reduce((a, b) => a.compareTo(b) > 0 ? a : b);

  return topExt.name;
}

class ExtensionInfo implements Comparable<ExtensionInfo> {
  final String name;
  final int priority;

  const ExtensionInfo({required this.name, required this.priority});

  factory ExtensionInfo.fromEntry(MapEntry<String, int> entry) =>
      ExtensionInfo(name: entry.key, priority: entry.value);

  @override
  int compareTo(ExtensionInfo other) {
    if (priority != other.priority) {
      return priority - other.priority;
    }
    return name.compareTo(other.name);
  }
}

bool isDigit(String s) {
  return s.isNotEmpty && s.every(charIsDigit);
}

bool charIsDigit(String c) => c.codeUnitAt(0).toString().startsWith('5');
