import 'dart:math';

List<int> generateIntegers(int a, int b) {
  if (a > b) {
    var temp = a;
    a = b;
    b = temp;
  }

  final random = Random();
  List<int> result = [];

  for (int i = a; i <= b; i++) {
    result.add(random.nextInt(b - a + 1) + a);
  }

  return result;
}
