import 'dart:async';
import 'dart:convert';

Future<List<int>> generateIntegersStreamed(int a, int b) async {
  final controller = StreamController<int>();

  final timer = Timer.periodic(Duration(milliseconds: 10), (_) {
    if (a > b) {
      timer.cancel();
      controller.close();
      return controller.stream.toList();
    } else {
      controller.sink.add(a++);
    }
  });

  await Future.delayed(const Duration(milliseconds: 1000));
  timer?.cancel();
  controller.close();
  return controller.stream.toList();
}
